mapper.select:
/* com.heeji.picket.mapper.PostMapper.list */ SELECT POST_ID AS postId , TYPE AS postType , TITLE AS title , CONTENT AS content , HITS AS hits , INSERT_DATE AS insertDate , INSERT_ID AS insertId , UPDATE_DATE AS updateDate , UPDATE_ID AS updateId FROM POST WHERE 1 = 1 AND TYPE = #{postType}
AND TITLE LIKE CONCAT('%', #{keyword}, '%')
ORDER BY POST_ID DESC
LIMIT #{size} OFFSET #{offset}

/* com.heeji.picket.mapper.PostMapper.count */
SELECT  COUNT(*)
FROM    POST
WHERE   1 = 1
AND     TYPE = #{postType}

AND     TITLE LIKE CONCAT('%', #{keyword}, '%')

mapper.update:
/* com.heeji.picket.mapper.PostMapper.increaseViewCount */
UPDATE  POST
SET     HITS = HITS + 1
WHERE   1 = 1
AND     POST_ID = #{postId}

/* com.heeji.picket.mapper.PostMapper.update */
UPDATE  POST
SET     UPDATE_DATE = NOW()
,       UPDATE_ID = #{loginId}
,       TITLE = #{title}
,       CONTENT = #{content}
WHERE   1 = 1
AND     POST_ID = #{postId}

mapper.delete:
/* com.heeji.picket.mapper.PostMapper.delete */
DELETE FROM POST
WHERE       1 = 1
AND         POST_ID = #{postId}
